  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (202::BIGINT, 'Excelente profesor, explica bien califica con amor y lo único es que dura mucho calificando pero de lo mejor que hay para física ii'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'cd590f63f7a99388b6a1df16f2221767e1c326ca6bc9a3ae03e4929920abb358'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, 'Si le molesta que duren entregando notas o no saber como le está yendo, no meta con él. Nos calificó todo el último día. Es un vago pero califica bonito y suave, es un amor, y pues cae muy bien. No da mucha retroalimentación y uno nunca sabe como va pero promete y si no le interesa el curso, mejor.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '68ffa2c152829d4427312cf315e3ba34c90f87f0561881a0c1f1a1b83debad28'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'Excelente profesor de Fisica I el en clase se dedica solo a leer el libro del curso por lo que recomiendo tener e irlo leyendo ademas de esto tarda su tiempo en revisar trabajos pero el profe califica suave, y se esmera bastante en explicar y en que uno entienda de donde salen las cosas, Recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ed807c0995b5dffb5588d15914c7f09fdc02b7ac9307f43888748a1663101e93'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'De los mejores profes para llevar fisica 2, no explica muy bien pero a como explica califica. Eso sí, deja la evaluación de los trabajos para final de semestre pero fuera de eso es de las mejores opciones para llevar el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '2cc027be50d57cda65f6b55f76fe475247b194f1b5a84c9b9ae04291b9801e81'::TEXT, ARRAY[630]::BIGINT[]),
    (202::BIGINT, 'Es muy amable, la explicación al inicio de la clase es clara y si a uno le pregunta por algo mientras se está armando el equipo ayuda. Padre ejemplar'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '2fef62650741be79396214ba00223f6c2beb92ba95c2bb6b0ffcfeec6643224e'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'Es bueno, solo que dura mucho en calificar las cosas, pero cuando lo hace es muy bueno. No es como super apasionado, pero es claro, explica bien y ayuda. Me cayó bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '2960e10e4063f48a391fdfa4a6e5e0daac1f77afae5be543083ba43111dadf42'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, 'Las clases son el copiando los ejemplos del libro, aún así siento que se esfuerza porque el estudiante entienda de donde salen las cosas, muy buena nota, ayuda mucho si usted pregunta personalmente, no responde correos, DURA DEMASIADO calificando, aun así califica suave.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'c25182b560b4506d34c029d768555d954d6c5f9c8c43ccfb754ea85d99766845'::TEXT, ARRAY[630]::BIGINT[]),
    (202::BIGINT, 'El profe es buena nota y siempre brinda ayuda cuando se le pregunta, eso sí, lo recomiendo solo si se está repitiendo la materia puesto que las explicaciones en clase son muy breves. Sube todo hasta el final. Califica suave.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '4e4c92cb7e0a6b1312596a72fa69e012759a21fb1e25c2a0be68118e557ca506'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, 'Demasiado VAGO, usted no sabe su nota casi que hasta el último dia ya que dura demasiado en subirlas. Es buena nota y explica regular. No contesta correos ni nada.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'a74dd133bdd5dee8653f71ad90486a2650f1c24f5c0df020f6223bd813dcf1ec'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'Física 2, curso extremadamente difícil, si no es que el más feo que hay. No me pareció que el profe calificara suave, fue normal. no hace quices(hace GAAP), regala puntaje con experimentos que deja. Buen profe pero tarda MUCHÍSIMO en calificar, una pura incertidumbre hasta el final a ver si unopasa'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '3047ea192b20c15286455e0eb578c05ce987bec0819d454ea9b49a2118eaee2d'::TEXT, ARRAY[630]::BIGINT[]),
    (202::BIGINT, 'El profe es DEMASIADO vago, a nivel de que en semana 18 tengo menos de un 20% a pesar de haber entregado absolutamente todo. Es buen profesor eso sí, la explicación antes del lab es muy buena y se interesa porque uno entienda bien qué pasa durante el laboratorio'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '1191bd2f221075f5ed671817f403cfb49dab71b5092a8971dd02b7a833d6417e'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'La clase es explicar los ejemplos del libro, no tiene asistencia obligatoria (solo las primeras 2-3 clases), califica demasiado demasiado suave. 100% recomendado si usted puede estudiar solo física, no hace quizzes, solo 2 tareas que son un regalo (son experimentos).'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '6b3cf8007b36508b210599a03afbed761d973d28fbd08cdaebcc00f7a7812dad'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, 'Es buena persona, ayuda en lo que puede, califica suave, no responde correos, sin embargo, los leé y los toma en cuenta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'ef0e9e4abb7c9d300dabedbf88d3d086957cc1b4ee2a992507b5cab44bf7f6cb'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'El mae es el ser mas vago que he visto en mi vida , sin embargo es tuanis y califica EXTREMADAMENTE SUAVE al punto de que las tareas las califica en si las entrega o no. Lo recomiendo si esta repitiendo el curso , si es su primera y siente que necesita alguien que lo guie tavito no es el indicado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'e4d72b2d3bea7ba92a735af670cab65778bacc9d2728e327cce0638c4e4f194e'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'Es un profe demasiado vago, si matricula con él, espere a que todos los trabajos los califique hasta semana 16, explica bien, todas sus clases se basan en el libro. Para darse cuenta si va bien o no, se sabe hasta semana 17 porque todo lo revisa tarde.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'bac86092c8d27a9a2440bf9d5840c96256099f581f492e4fe3dec7df6dfd2ae0'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'Es muy buena gente y en consulta ayuda bastante y explica cualquier cosa que no quede clara en clase, tarda mucho en revisar los trabajos, es compresible, deja dos proyectos super fáciles, la asisten califica raro es mejor siempre volver a revisar las tareas con el, califica algo suave'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fa6656fd95c4050dd214b533510f486f113eab3995529b9816d6786ef6ada6ad'::TEXT, ARRAY[630]::BIGINT[]),
    (202::BIGINT, 'Explica bien los conceptos de geometría y mates previas que son bastante importantes para el curso. Bastante ánimo al responder dudas. Ayuda montones con las evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '726dbb3cbd3e45a4edab195279b6aa6f06d61b7cabc8c318278549a1c600d586'::TEXT, ARRAY[630]::BIGINT[]),
    (202::BIGINT, 'El profe faltó 3 veces, no repuso esas clases. Duro DEMASIADO en subir notas. A veces no estaba en horario de consulta. El curso es difícil y pienso que puede el profe cubrir mejor la materia. Hay que hacer demasiada práctica para pasar y asistir a consulta.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'edd415d6d5d15bea3e7e5e05ffb7fb692a15ed0d1d0a6d875b69fc223a0baeb9'::TEXT, ARRAY[630]::BIGINT[]),
    (202::BIGINT, 'El curso como tal es difícil, pero el profe es muy buena persona y si vas a consulta te ayuda demasiado, explica regular, no profundiza mucho en los temas, pero si vas a consulta te aclara cualquier duda, no hace quices, solo dos proyectos que dejo para el final y dura mucho revisando evaluaciones.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '62ba2357e5f0f9c1c8ad190762fef08c909b09735a447ac6403a5c957f5c816d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, 'Para nada recomendado, entrega evaluaciones en semana 17, muy desordenado y explica de un libro anticuado. Lo único bueno es que no hace que su clase sea de asistencia obligatoria'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '7bd816587b0098cb27e19aadbc12a08df68fefa1d603a939368c196a0f74f629'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'Las clases son pura práctica del libro de consulta. Reviso TODAS las evaluaciones en semana 18, si sos medio apuntado eso te asegura casi que más de 80 en todas las evaluaciones aparte de los exámenes. *Lo recomiendo si estás repitiendo.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9885646ba37baf94c0790277b38a2f9eb17f7e966f03a5a95329237c9ea6efa5'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'El profe es buena gente, sin embargo ve la materia un poco por encima, practicamente lee lo que está en el libro y copia los ejemplos del mismo. En general física 2 es complicado pero con él hay que ser autodidacta y profundizar más en la materia, fuera de eso no está tan mal.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1e96121cd056c1a8ec53d3245a456d8b09d61d6f340a4452db07373a99bf9163'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, 'El profe es medio vaguillo pero califica EXTREMADAMENTE suave y te da tiempo de entregar cosas tarde y así, muy relajado.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'e395b4c238750ea71b6b15c9b4a2dd7e98126e6ec6c69b13b5659546b7c6f182'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (202::BIGINT, 'Está bien, califica suave y es flexible. Algo impuntual'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7b49e54965ee736f29d0199e5b3036ec737ec67a85207ee84275816f762115f2'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'El profe es algo confuso a la hora de explicar pero brinda ayuda, es mejor guiarse siempre con lo que sube la catedra, califica suave casi que me atrevería a decir que ni revisa solo ve si fue entregado, hasta semana 18 medio sube notas'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '667f1494ffc879bf7a29b3a1d8066a8a381b8aa05d5e3a03830752791430e83a'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'El profesor fue muy mediocre, puesto que llegaba siempre tarde y nunca califico las evaluaciones, si no, hasta el puro final del semestre. Pero, esto a su vez viene con la ventaja de que califica prácticamente en base a si entregaste el trabajo o no, provocando que sea fácil de pasar el curso con el'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1e9f2d299ae9d1bb7b3ffa07f68e6cb0feef5bf59aae0f92387fe8053f57ade9'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'Es muy accesible con las dudas, aunque no se explica muy bien, atiende a cualquier hora, solo que únicamente por zoom, no responde mensajes al privado. Revisó todo en la última semana del semestre. Califica suave.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '7f28674c9813c956f48caaa9e6bd751057728a9da1a298a3fd93cad0795ae845'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (202::BIGINT, '(Virtual) Muy llevadero, las clases solo eran para explicar lo que se va a hacer pero revisó todo a final de semestre.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '6832a47dc572174b7df4994152b6305d69af6fe4ba526f20721612977df734eb'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'profe muy meh. Opción a matricular cuando ya no haya campo con los buenos profes Virtualmente practicamente se pasa con el material de la cátedra, ni es necesario ir a clases'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'b7d1b89378b7c11e03bb1a26f2f3ae0fba16cee2f1fc080a7c66ad0327c1676d'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'Pasar con el es fácil, califica suave aunque para hacer el curso más llevadero recomiendo que el profesor que les de teoría si sea muy bueno. Es muy claro con las instrucciones aunque no es muy bueno explicando la materia'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'da9622082ad05462fdb64e66b2d6bf15a3134c7b57403d7b3163aa29b380671e'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'No podría decir mucho sobre sus clases porque el curso virtual casi que todo lo aporta la cátedra. En general él deja las cosas puntuales muy claras, pero cuesta muchísimo que le responda preguntas. Califica muy suave. Al menos virtual más que el profesor, importa los compañeros que le toquen'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'af22cac5a0b62292e3e350eb97f571557aee9619d92ba10e050708431340b62e'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'Me brindo ayuda cuando se la pedí pero no me aclaraba las dudas correctamente. Tardo demasiado en subir las notas , pero califica sumamente suave , el curso se pasa con una nota súper buena'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '1b4b211d1fbd2e3ffd7caf3b921d76016a008ee1e87ed6f892cca37ee4e8e566'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'No ayuda mucho, y la mayoria de trabajos son en grupo. Pero no es dificil de pasar el curso con él.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'e73d0cb5d7056f37e5d6a34f84ae2188bf6dc9f42df30ec93730253f5db9b4a5'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'En general no es tan malo pero si es cierto que no ayuda, nunca da clases y deja todo a los estudiantes casi sin ayuda, es fácil pasar con buena nota, ya que califica super suave y la materia se presta.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-01-23T00:00:00+00:00'::TIMESTAMPTZ, '471edac588ec9c25780b0083b4e48ae4c7f5b5c86d38610567689fcecd05e5f6'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'no responde dudas por los grupos, solo a veces responde por privado, no hay clases sincrónicas, no está claro lo que se debe hacer, hay que guiarse solamente con lo que publica la cátedra, y no entrega notas de reportes e informes hasta el último día, al final califica suave'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '8a061cb1f5bb027a5cbec7aa177c48bb5bd6fab385a7d4547c03080c161ea3fd'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'No sube reporte de notas hasta al final. Cuesta mucho que responda correos, prácticamente usted se la juega solo con lo de la cátedra. El curso no es difícil, pero sepa que va a tener que jugársela solo. Hay muchas clases asincrónicas.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'ebaaf3626b8dff5094ec2475966b14abd4d3fda8eb0e3946bc6484360ab7e256'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'No lo haga, el mae se presentó la primera clase y no se supo más de él hasta el día de la presentación oral en semana 16 no responde correos ni mensajes es un fantasma en todo el curso lectivo, al día de hoy ya casi termina el año y no se si pasaré o no pasaré el curso, no lo recomiendo para nada'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-12-30T00:00:00+00:00'::TIMESTAMPTZ, '5f437b595e084061145924dbfb270189da2637177b7d23bbfb6452ac17eb1824'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'No lo recomiendo llevar en virtual, deja solos a los estudiantes y no resuelve dudas, ya es final de semestre y no brindó notas de informes ni reportes.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'c6ba19a03b592ce633fa3c8cc4a20caf8e0e43153a408930c905c582e3c20488'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'Muy lento para dar las notas'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '3b27d5dc87d7480a9dea7610a03a7de2bd0f4f5bd9dde271e634ecd608b5b245'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'El curso virtual prácticamente se pasa solo, no hay mucho que hacer o aprender, pero el profe siempre duraba mucho en responder o explicar dudas. También tardaba mucho en dar las calificaciones de los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '0e472ec4b7d4be369aabf95799759d9cfad4454146e927e41c60d6c050050070'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'En el semestre virtual, duró bastante en entregar las notas de los informes de la cátedra, además calificó duro y no utilizó rubricas, por ende no se sabía cuales eran los errores. Desde las primeras clases presenciales antes de CV, se notaba el desinterés por impartir el curso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '25bdd72b320326087b842310a6ea4cadfee2d7e57093f2cb828b274be01f1648'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'No lo recomiendo para llevarlo virtual, en presencial atendía las dudas de los estudiantes, pero un virtual lo dejó a uno solo, no explicaba las practicas semanales ni mucho menos los informes, además, en ocasiones tardaba mucho en atender las dudas y los trabajos los calificó super tarde.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '5e0e64edc85fadaae77988fa2030d64d8b90e5c9340a0e2509e410ea983cb748'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '63c1cc2894002740c65b97f8350cce63dd00fbb3ec3b9721d00bb9be764495f6'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'Da una explicación antes del laboratorio, y si se requiere explica las veces que sean necesarias. Dura mucho en calificar los reportes, y demás evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'a2be58d1701f119c9fd762767c7f8fb1d5bab98693f72a4c0356e32e29de503b'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'Es super fácil pasar con este profe , SIN EMBARGO, esta extremadamente perdido con todo. Te ayuda las veces que sea necesario pero le falta empaparse un poco más de las prácticas o como tratarlas'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'ff06a4b619dfe762126ca8fd9da31d7f246962b04ecdc428e624d212c7288ac7'::TEXT, ARRAY[631]::BIGINT[]),
    (202::BIGINT, 'El profe es super bueno, cada vez que necesites ayuda él te la dará. Es claro en como deben de ser los trabajos. Evalúa normal, se deben de hacer los informes y experiencias a conciencia y bien hechos, si no no espere una buena nota. En general a mí me pareció muy bueno. No llevaría teoría con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, '7236a4df7c7e3b11376ff05d4ae980734192905e2541abd98a5243f01f289e3d'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'El profe explica bien, sólo que le falta un poco de motivación para dar las clases, ayuda las veces que sea necesario.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-08-16T00:00:00+00:00'::TIMESTAMPTZ, '55915a2c33e5e149b8d383f6bd4097c8407d37a2d8504337e9072022ee120b04'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'El mae es buena nota y si usted le pone atención y hace los informes y las experiencias a conciencia, el curso es fácil. Eso sí, el mae es demasiado irresponsable a la hora de entregar las notas de las evaluaciones, pero en lo demás no es tan malo profe.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-09T00:00:00+00:00'::TIMESTAMPTZ, '310c8e6d4e15b9a6f57ec4a6fc381cf75051660fabada1576352ab60ff05c485'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'Clases baratas y desinteresadas'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '652317564af628ccac7d6f583680b1a55ff3feddd63fc94b5393fc39d4eac91a'::TEXT, ARRAY[607]::BIGINT[]),
    (202::BIGINT, 'No sabe explicar y enreda a los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-15T00:00:00+00:00'::TIMESTAMPTZ, '3a12094cf12767bcc0dc22f11b699b52dfaa1459b0556810a12a91188dec5800'::TEXT, ARRAY[3257]::BIGINT[]),
    (202::BIGINT, 'Para alguien que repite el curso es súper bueno, porque va preparado para la clase, da lo importante y sus ejemplos a veces son claros, otras veces hay que preguntarle para que explique cómo se aplica en algunos ejemplos. Las clases son muy claras y resuelve las dudas que usted lleve.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '9a1ee658f2d1994a8dcb6eb37b5d21db0b789d4a51b16c9ac539cda3b29cd4b6'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'Para verano es un profe excelente, lleva la clase con buen ritmo y preparada de forma que todo queda claro y se preocupa por que todos entiendan. Los exámenes lo hace complicados pero si uno practica lo suficiente el curso es llevadero'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '4da834a1e5ad3b97e2519076919bfad272d052fee7ada7248216a0e106c82619'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'profe pésimo, solo da un ejemplo por tema, va despichado en la materia, entrega trabajos y examenes tarde, es la fecha de hoy y la amplia de fisica es el lunes y el mae no ha entregado nada, legalmente el mae es buena nota pero no lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ea982ee36c118bcf6b61c194597b6370d8b3be00810f68d48258a9cef3e6f5c5'::TEXT, ARRAY[604]::BIGINT[]),
    (202::BIGINT, 'Buena persona pero muy mal profe. Se complica demasiado y no logra explicar lo que hace. Francamente para alguien que quiere aprender y aprobar la materia bien no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '66da391def8de5849cb5554c83862753824a13a0bece39b931b37f73385bb60d'::TEXT, ARRAY[3257]::BIGINT[]),
    (202::BIGINT, 'Muy mal Profe, aunque una buena persona, hasta cierto punto le importa el bienestar de los estudiantes pero si no sabe de física, le interesa aprender y sacar buena nota NO META CON ÉL. Nunca termina de ver la materia y da 1 ejemplo por tema'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '89e4a6f7d69389e2d9e38aca24612db8b2ec6dab41e2a2d37c628df791eeb0b4'::TEXT, ARRAY[3257]::BIGINT[]),
    (202::BIGINT, 'Se complica mucho en clase, no manda prácticas, uno se va al examen sin practicar. En clase solo hace un ejercicio por tema y nunca los termina o no le dan bien y dura toda la lección haciéndolo... Se supone que iba a hacer muchos quices para ayudarnos y solo hizo uno... entrega exámenes TARDE'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '965a5c5d24d56a4e39e1844a227d77a2b4f1fe06825a5a99e1e08f2e7c90c384'::TEXT, ARRAY[3257]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
